"""1. Get_Data.py - pull every raw table the career-tenure deep dive needs, to S3.Writes to s3://<bucket>/static-ds-analyses/career-tenure/:  player_seasons.parquet   one row per player-season (skaters + goalies), 1917-2026  skater_seasons.parquet   one row per skater-season, with scoring  skater_bios.parquet      one row per skater: birth date, draft, Hall of Fame  team_seasons.parquet     one row per team-season: games, wins, points  team_rosters.parquet     one row per player-team-season, games for THAT teamWritten for cell-by-cell execution in Spyder (Ctrl+Enter through the # %% cells).It also runs top-to-bottom as a plain script.Why team_rosters is pulled team by team---------------------------------------The season-wide summary endpoint returns a traded player as ONE row withteamAbbrevs="WSH,TOR" and his combined games, so his experience cannot beattributed to either roster. Adding teamId to the cayenne filter splits him:Joel Edmundson 2023-24 comes back as 9 games under teamId=10, not 53. Thatcosts ~4,100 requests instead of ~220 - about 35 minutes.Why not nhl-player-demographics/rosters.csv-------------------------------------------That file is built from api-web.nhle.com/v1/roster/{team}/{season}, whichreturns partial data for recent seasons: 2023-24 is missing ~37% of players,2024-25 ~16%, and Toronto is absent from 2022-23 entirely. This script usesapi.nhle.com/stats/rest/en/{skater,goalie}/summary, which returns every playerwith a regular-season appearance."""# imports and configurationimport sysimport timefrom pathlib import Pathimport pandas as pdimport requestsimport s3fs# Spyder does not define __file__ when you execute a single cell, only under# F5/runfile. Fall back to the hardcoded root, the way test_master_write.py does.try:    REPO = Path(__file__).resolve().parents[2]except NameError:    REPO = Path("/Users/dwiwad/dev/hockey_site")sys.path.insert(0, str(REPO))try:    from app.core.config import S3_BUCKETexcept (ImportError, KeyError):    S3_BUCKET = "hockey-decoded"SLUG = "career-tenure"PREFIX = f"static-ds-analyses/{SLUG}"CACHE = REPO / "data" / SLUG / "cache"          # gitignored; S3 is source of truthBASE = "https://api.nhle.com/stats/rest/en"PACE = 0.4                                      # seconds between requests# ---- edit these, then run the cells below ----------------------------------FORCE_LEAGUE = True      # the 6-season tables need replacingFORCE_TEAMS = False      # team_rosters is already correct at 57,186FIRST_SEASON = 1917LAST_SEASON = 2026SEASONS = [int(f"{y}{y+1}") for y in range(FIRST_SEASON, LAST_SEASON)]print(f"{len(SEASONS)} seasons, {FIRST_SEASON}-{LAST_SEASON} "      f"-> s3://{S3_BUCKET}/{PREFIX}/")# helpers - httpSESSION = requests.Session()          # one connection pool for ~4,100 requestsdef fetch(path, cayenne, retries=6):    """Run one cayenne query against the stats API and return its `data` list.    `path` is the endpoint after /en/, e.g. "skater/summary" or "team/summary".    `cayenne` is the filter expression, e.g. "seasonId=20232024 and gameTypeId=2".    Two behaviours worth knowing:    * The API rate-limits at roughly a hundred requests in quick succession. A      429 therefore sleeps for the full Retry-After (or an exponential fallback)      rather than retrying straight into the same wall.    * It RAISES when every attempt fails, and never returns an empty list to      paper over an error. A silent `except: pass` is what left gaps in the      demographics roster file in the first place.    """    last = None    for attempt in range(retries):        try:            r = SESSION.get(f"{BASE}/{path}",                            params={"cayenneExp": cayenne, "limit": -1},                            timeout=45)            if r.status_code == 429:                wait = float(r.headers.get("Retry-After", 0)) or 10 * 2 ** attempt                print(f"    429 - sleeping {wait:.0f}s", flush=True)                time.sleep(wait)                last = "429"                continue            r.raise_for_status()            time.sleep(PACE)            return r.json().get("data", [])        except Exception as e:      # noqa: BLE001 - retried with backoff, never dropped            last = e            time.sleep(2.0 * (attempt + 1))    raise RuntimeError(f"{path} [{cayenne}] failed after {retries} attempts: {last}")# helpers - s3FS = s3fs.S3FileSystem(anon=False)    # picks up your AWS credentialsdef s3_uri(name):    """Full s3:// URI for one table, for pandas."""    return f"s3://{S3_BUCKET}/{PREFIX}/{name}.parquet"def in_s3(name):    """True if the table already exists. s3fs wants bucket/key, no scheme."""    return FS.exists(f"{S3_BUCKET}/{PREFIX}/{name}.parquet")def write(df, name):    """Write one table to S3.    S3 has no directories - the key prefix IS the folder, so this call is what    brings static-ds-analyses/career-tenure/ into existence. Nothing to create    beforehand.    Guards against writing an empty table: silently uploading a zero-row file    over good data is the failure that would be hardest to notice later.    """    if df.empty:        raise ValueError(f"refusing to write an empty table: {name}")    df.to_parquet(s3_uri(name), storage_options={"anon": False}, index=False)    print(f"  wrote {s3_uri(name)}  ({len(df):,} rows)")    # helpers - the two pullsdef pull_league(seasons):    """Season-wide tables: every player, every skater's scoring, every bio.    One skater/summary call per season feeds BOTH player_seasons and    skater_seasons. The original scratch scripts each made their own, which was    109 redundant requests and left two tables free to drift apart.    Returns (players, scoring, bios) so the frames land in the Variable    Explorer, not just in S3.    """    players, scoring, bios = [], [], []    for season in seasons:        sk = fetch("skater/summary", f"seasonId={season} and gameTypeId=2")        go = fetch("goalie/summary", f"seasonId={season} and gameTypeId=2")        bi = fetch("skater/bios", f"seasonId={season} and gameTypeId=2")        for d in sk:            players.append({"playerId": d["playerId"], "season": season,                            "team": d["teamAbbrevs"], "games_played": d["gamesPlayed"],                            "position": d["positionCode"], "name": d["skaterFullName"]})            scoring.append({"playerId": d["playerId"], "season": season,                            "games_played": d["gamesPlayed"], "points": d["points"],                            "goals": d["goals"], "assists": d["assists"],                            "position": d["positionCode"], "name": d["skaterFullName"]})        # goalies have no positionCode and a different name field        for d in go:            players.append({"playerId": d["playerId"], "season": season,                            "team": d["teamAbbrevs"], "games_played": d["gamesPlayed"],                            "position": "G", "name": d["goalieFullName"]})        for d in bi:            bios.append({"playerId": d["playerId"], "name": d["skaterFullName"],                         "birth_date": d.get("birthDate"),                         "draft_year": d.get("draftYear"),                         "draft_overall": d.get("draftOverall"),                         "hof": d.get("isInHallOfFameYn") == "Y",                         "nationality": d.get("nationalityCode")})        print(f"  {season}  skaters={len(sk):>4}  goalies={len(go):>3}", flush=True)    players_df = pd.DataFrame(players)    scoring_df = pd.DataFrame(scoring)    # A player appears in bios once per season he played, and the Hall of Fame    # flag is only true on the later rows. Sort hof-first so the row that keeps    # the flag is the one that survives the dedupe - a naive drop_duplicates    # here would zero out most Hall of Famers.    bios_df = (pd.DataFrame(bios)               .sort_values("hof", ascending=False)               .drop_duplicates("playerId", keep="first"))    write(players_df, "player_seasons")    write(scoring_df, "skater_seasons")    write(bios_df, "skater_bios")    return players_df, scoring_df, bios_dfdef pull_teams(seasons, force=False):    """Team standings, then per-team rosters - the expensive half.    Each season's rosters are cached to data/career-tenure/cache/ the moment    they land, so an interrupted run resumes instead of restarting 35 minutes    of requests. Delete that directory (or pass force=True) for a cold rebuild.    Returns (team_seasons, team_rosters).    """    CACHE.mkdir(parents=True, exist_ok=True)    # --- standings: one request per season -------------------------------    standings = []    for season in seasons:        for d in fetch("team/summary", f"seasonId={season} and gameTypeId=2"):            standings.append({                "season": season, "teamId": d["teamId"], "team": d["teamFullName"],                "gp": d["gamesPlayed"], "wins": d["wins"], "losses": d["losses"],                "ties": d.get("ties"), "otl": d.get("otLosses"),                "points": d["points"], "point_pct": d["pointPct"],                "gf": d["goalsFor"], "ga": d["goalsAgainst"]})    ts = pd.DataFrame(standings)    write(ts, "team_seasons")    # --- rosters: two requests per team per season ------------------------    # The teamId in the filter is the whole point: it is what splits a traded    # player into one row per club instead of one combined row.    for season in seasons:        cached = CACHE / f"roster_{season}.parquet"        if cached.exists() and not force:            continue        rows = []        ids = ts.loc[ts.season == season, "teamId"].tolist()        for tid in ids:            cay = f"seasonId={season} and gameTypeId=2 and teamId={tid}"            for d in fetch("skater/summary", cay):                rows.append({"playerId": d["playerId"], "season": season,                             "teamId": tid, "gp": d["gamesPlayed"],                             "position": d["positionCode"],                             "name": d["skaterFullName"]})            for d in fetch("goalie/summary", cay):                rows.append({"playerId": d["playerId"], "season": season,                             "teamId": tid, "gp": d["gamesPlayed"],                             "position": "G", "name": d["goalieFullName"]})        # 2004-05 was cancelled and returns zero teams; the empty file is        # correct and concat below handles it.        pd.DataFrame(rows).to_parquet(cached, index=False)        print(f"  {season}  teams={len(ids):>2}  rows={len(rows):>5}", flush=True)    tr = pd.concat([pd.read_parquet(CACHE / f"roster_{s}.parquet") for s in seasons],                   ignore_index=True)    write(tr, "team_rosters")    multi = tr.groupby(["playerId", "season"]).teamId.nunique().gt(1).sum()    print(f"  multi-team player-seasons split correctly: {multi:,}")    return ts, tr# run - league-wide tables  (~5 min on the full sweep)if FORCE_LEAGUE or not all(in_s3(n) for n in                           ["player_seasons", "skater_seasons", "skater_bios"]):    player_seasons, skater_seasons, skater_bios = pull_league(SEASONS)else:    print("league tables already in S3 - reading them back instead")    player_seasons = pd.read_parquet(s3_uri("player_seasons"),                                     storage_options={"anon": False})    skater_seasons = pd.read_parquet(s3_uri("skater_seasons"),                                     storage_options={"anon": False})    skater_bios = pd.read_parquet(s3_uri("skater_bios"),                                  storage_options={"anon": False})# run - team tables  (~35 min on the full sweep; Spyder will look frozen)if FORCE_TEAMS or not all(in_s3(n) for n in ["team_seasons", "team_rosters"]):    team_seasons, team_rosters = pull_teams(SEASONS, force=FORCE_TEAMS)else:    print("team tables already in S3 - reading them back instead")    team_seasons = pd.read_parquet(s3_uri("team_seasons"),                                   storage_options={"anon": False})    team_rosters = pd.read_parquet(s3_uri("team_rosters"),                                   storage_options={"anon": False})# verifyprint(f"player_seasons  {len(player_seasons):>7,} rows  "      f"{player_seasons.playerId.nunique():,} players  "      f"{player_seasons.season.nunique()} seasons")print(f"skater_seasons  {len(skater_seasons):>7,} rows")print(f"skater_bios     {len(skater_bios):>7,} rows  "      f"{int(skater_bios.hof.sum()):,} Hall of Famers")print(f"team_seasons    {len(team_seasons):>7,} rows  "      f"{team_seasons.teamId.nunique()} franchises")print(f"team_rosters    {len(team_rosters):>7,} rows")# The debut year every downstream metric keys off. No left-truncation: the NHL# starts in 1917-18, so on a full sweep every player's first season is observed.debut = team_rosters.assign(yr=team_rosters.season // 10000).groupby("playerId").yr.min()exp = (team_rosters.season // 10000) - team_rosters.playerId.map(debut)assert exp.min() >= 0, "negative experience - debut years are wrong"print(f"\nexperience 0-{exp.max()} seasons, no negatives")